window.MOCK={"subj":"nss","stitle":"Networks, Signals & Systems","n":27,"title":"IIR Filters","marks":293,"qs":[{"i":1,"q":"Find the minimum Butterworth order for a pass-band edge 1000 rad/s with at most 2 dB loss and a stop-band edge 3000 rad/s with at least 60 dB attenuation.","f":null,"o":["$6$","$14$","$7$","$8$"],"a":2,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1.71\\times10^{6}]}{2\\log(3)}=6.532$ ⇒ $N=7$.","m":2,"t":"Butterworth order from specifications"},{"i":2,"q":"Find the minimum Butterworth order for a pass-band edge 500 rad/s with at most 2 dB loss and a stop-band edge 2000 rad/s with at least 20 dB attenuation.","f":null,"o":["$4$","$3$","$1$","$2$"],"a":3,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[169.3]}{2\\log(4)}=1.851$ ⇒ $N=2$.","m":2,"t":"Butterworth order from specifications"},{"i":3,"q":"$H_a(s)=\\dfrac{1000}{s+1000}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$0.05$","$0.09524$","$1$","$0$"],"a":2,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":4,"q":"Find the minimum Butterworth order for a pass-band edge 1000 rad/s with at most 2 dB loss and a stop-band edge 1500 rad/s with at least 60 dB attenuation.","f":null,"o":["$18$","$19$","$36$","$17$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1.71\\times10^{6}]}{2\\log(1.5)}=17.7$ ⇒ $N=18$.","m":2,"t":"Butterworth order from specifications"},{"i":5,"q":"Find the minimum Butterworth order for a pass-band edge 500 rad/s with at most 2 dB loss and a stop-band edge 1000 rad/s with at least 50 dB attenuation.","f":null,"o":["$9$","$18$","$8$","$10$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1.71\\times10^{5}]}{2\\log(2)}=8.692$ ⇒ $N=9$.","m":2,"t":"Butterworth order from specifications"},{"i":6,"q":"Find the minimum Butterworth order for a pass-band edge 200 rad/s with at most 1 dB loss and a stop-band edge 800 rad/s with at least 30 dB attenuation.","f":null,"o":["$3$","$2$","$4$","$6$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[3858]}{2\\log(4)}=2.978$ ⇒ $N=3$.","m":2,"t":"Butterworth order from specifications"},{"i":7,"q":"For the same digital cut-off ($f_c=3400$ Hz, $f_s=44100$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)","$\\omega_a=\\pi f_c$","$\\omega_a=2\\pi f_c$ always","$\\omega_a&lt;2\\pi f_c$"],"a":0,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=2.179\\times10^{4}$ rad/s versus $2\\pi f_c=2.136\\times10^{4}$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":8,"q":"A resonator has poles at $z=0.9e^{\\pm j2\\pi/3}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_1$.","f":null,"o":["$0.9$","$-1.8$","$-0.9$","$0.81$"],"a":0,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.9)\\cos(2\\pi/3)=0.9$, $c_2=0.81$.","m":2,"t":"Resonator pole placement"},{"i":9,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.6z^{-1})(1-0.4z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_1$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$1$","$0.24$","$-0.5$","$-1$"],"a":3,"s":"Expand: $(1-0.6z^{-1})(1-0.4z^{-1})=1-(1)z^{-1}+(0.24)z^{-2}$ ⇒ $c_1=-1$, $c_2=0.24$.","m":2,"t":"Cascade and parallel realisations"},{"i":10,"q":"Find the minimum Butterworth order for a pass-band edge 200 rad/s with at most 3 dB loss and a stop-band edge 800 rad/s with at least 50 dB attenuation.","f":null,"o":["$5$","$6$","$4$","$9$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1.005\\times10^{5}]}{2\\log(4)}=4.154$ ⇒ $N=5$.","m":2,"t":"Butterworth order from specifications"},{"i":11,"q":"A resonator has poles at $z=0.5e^{\\pm j\\pi/4}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_2$.","f":null,"o":["$0.5$","$0.125$","$0.25$","$-0.7071$"],"a":2,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.5)\\cos(\\pi/4)=-0.7071$, $c_2=0.25$.","m":2,"t":"Resonator pole placement"},{"i":12,"q":"$H_a(s)=\\dfrac{1000}{s+1000}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$1$","$0$","$0.5$","$0.6667$"],"a":0,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":13,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{3}b_kz^{-k}}{1-\\sum_{k=1}^{3}a_kz^{-k}}$ is realised in direct form I. How many unit delays are needed?","f":null,"o":["$7$","$3$","$6$","$9$"],"a":2,"s":"Direct form I stores $M$ past inputs and $N$ past outputs: $3+3=6$.","m":2,"t":"Direct-form structures (hardware)"},{"i":14,"q":"A Butterworth low-pass filter of order 3 has cut-off $\\omega_c=1000$ rad/s. Find $|H(j\\omega)|$ at $\\omega=2000$ rad/s.","f":null,"o":["$0.124$","$0.3333$","$0.7071$","$0.01538$"],"a":0,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+2^{6}}$ ⇒ $|H|=0.124$.","m":2,"t":"Butterworth magnitude"},{"i":15,"q":"An analog filter has its 3-dB frequency at $\\omega_a=633.5$ rad/s. It is mapped by the bilinear transform with $T_s=1/2000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.3142$","$0.6135$","$0.1571$","$0.3168$"],"a":0,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.1584)=0.3142$ rad (compare the naive $\\omega_aT_s=0.3168$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":16,"q":"A digital filter must have its cut-off at $f_c=3400$ Hz when sampled at $f_s=8000$ Hz. Find the digital cut-off frequency $\\Omega_c$ in rad/sample.","f":null,"o":["$1.335$","$0.425$","$2.136\\times10^{4}$","$2.67$"],"a":3,"s":"$\\Omega_c=2\\pi f_c/f_s=2.67$ rad/sample.","m":2,"t":"Digital cut-off from analog specs"},{"i":17,"q":"A digital filter must have its cut-off at $f_c=500$ Hz when sampled at $f_s=16000$ Hz. Find the digital cut-off frequency $\\Omega_c$ in rad/sample.","f":null,"o":["$0.09817$","$0.03125$","$3142$","$0.1963$"],"a":3,"s":"$\\Omega_c=2\\pi f_c/f_s=0.1963$ rad/sample.","m":2,"t":"Digital cut-off from analog specs"},{"i":18,"q":"The poles of an order-3 Butterworth low-pass filter lie on a circle of radius $\\omega_c$. How many of the $2N$ roots belong to $H(s)$ (stable, causal)?","f":null,"o":["$3$","$4$","$6$","$2$"],"a":0,"s":"Only the 3 roots in the left half-plane are used for $H(s)$; the others belong to $H(-s)$.","m":2,"t":"Butterworth poles"},{"i":19,"q":"Find the minimum Butterworth order for a pass-band edge 200 rad/s with at most 3 dB loss and a stop-band edge 600 rad/s with at least 40 dB attenuation.","f":null,"o":["$5$","$6$","$9$","$4$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1.005\\times10^{4}]}{2\\log(3)}=4.194$ ⇒ $N=5$.","m":2,"t":"Butterworth order from specifications"},{"i":20,"q":"The $N=3$ poles of a Butterworth filter in the left half-plane are equally spaced on the circle. What is the angular spacing between adjacent poles (degrees)?","f":null,"o":["$30^\\circ$","$45^\\circ$","$120^\\circ$","$60^\\circ$"],"a":3,"s":"The $2N$ roots are spaced $\\pi/N$ apart: $180^\\circ/3=60^\\circ$.","m":2,"t":"Butterworth poles"},{"i":21,"q":"Find the minimum Butterworth order for a pass-band edge 200 rad/s with at most 3 dB loss and a stop-band edge 800 rad/s with at least 60 dB attenuation.","f":null,"o":["$10$","$6$","$5$","$4$"],"a":2,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1.005\\times10^{6}]}{2\\log(4)}=4.985$ ⇒ $N=5$.","m":2,"t":"Butterworth order from specifications"},{"i":22,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{1}b_kz^{-k}}{1-\\sum_{k=1}^{2}a_kz^{-k}}$ is realised in direct form II (canonical). How many unit delays are needed?","f":"<svg class=\"fg\" viewBox=\"0 0 330 190\" width=\"396\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 40.0L59.0 40.0\"/><path class=\"f\" d=\"M59.0 40.0L53.5 42.3L53.5 37.7Z\"/><text class=\"t\" x=\"8.0\" y=\"26.0\" text-anchor=\"start\">x[n]</text><circle class=\"w\" cx=\"70.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"70.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M80.0 40.0L260.0 40.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"40.0\" r=\"3\"/><text class=\"t\" x=\"176.0\" y=\"32.0\" text-anchor=\"middle\" style=\"font-size:11px\">b0 = 1</text><circle class=\"w\" cx=\"270.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"270.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M280.0 40.0L322.0 40.0\"/><path class=\"f\" d=\"M322.0 40.0L316.5 42.3L316.5 37.7Z\"/><text class=\"t\" x=\"324.0\" y=\"26.0\" text-anchor=\"end\">y[n]</text><path class=\"w\" d=\"M140.0 40.0L140.0 58.0\"/><rect class=\"w\" x=\"120.0\" y=\"58.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"74.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 82.0L140.0 100.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"100.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 100.0L140.0 118.0\"/><rect class=\"w\" x=\"120.0\" y=\"118.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"134.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 142.0L140.0 160.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"160.0\" r=\"3\"/><path class=\"w\" d=\"M70.0 50.0L70.0 160.0\"/><path class=\"w\" d=\"M140.0 100.0L70.0 100.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">a1 = 0.4</text><path class=\"w\" d=\"M140.0 160.0L70.0 160.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">a2 = 0.4</text><path class=\"w\" d=\"M270.0 50.0L270.0 100.0\"/><path class=\"w\" d=\"M140.0 100.0L270.0 100.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">b1 = 0.5</text></svg>","o":["$3$","$2$","$1$","$4$"],"a":1,"s":"The canonical form shares the delays: $\\max(M,N)=\\max(1,2)=2$.","m":2,"t":"Direct-form structures (hardware)"},{"i":23,"q":"An analog filter has its 3-dB frequency at $\\omega_a=6627$ rad/s. It is mapped by the bilinear transform with $T_s=1/8000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.8284$","$0.3927$","$1.384$","$0.7854$"],"a":3,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.4142)=0.7854$ rad (compare the naive $\\omega_aT_s=0.8284$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":24,"q":"Compared with Butterworth, a Chebyshev type-I filter of the same order has …","f":null,"o":["no ripple anywhere","a wider transition band","a flatter pass-band","a steeper roll-off but ripple in the pass-band"],"a":3,"s":"Equiripple pass-band, monotonic stop-band.","m":1,"t":"IIR design concepts"},{"i":25,"q":"For the same digital cut-off ($f_c=1000$ Hz, $f_s=44100$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)","$\\omega_a=2\\pi f_c$ always","$\\omega_a&lt;2\\pi f_c$","$\\omega_a=\\pi f_c$"],"a":0,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=6294$ rad/s versus $2\\pi f_c=6283$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":26,"q":"A Butterworth low-pass filter of order 6 has cut-off $\\omega_c=100$ rad/s. Find $|H(j\\omega)|$ at $\\omega=200$ rad/s.","f":null,"o":["$0.124$","$0.01562$","$0.0002441$","$0.7071$"],"a":1,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+2^{12}}$ ⇒ $|H|=0.01562$.","m":2,"t":"Butterworth magnitude"},{"i":27,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1--0.5z^{-1})(1--0.25z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_1$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$1.25$","$0.125$","$0.75$","$-0.75$"],"a":2,"s":"Expand: $(1--0.5z^{-1})(1--0.25z^{-1})=1-(-0.75)z^{-1}+(0.125)z^{-2}$ ⇒ $c_1=0.75$, $c_2=0.125$.","m":2,"t":"Cascade and parallel realisations"},{"i":28,"q":"A parallel realisation uses $H(z)=\\dfrac{2}{1-0.5z^{-1}}+\\dfrac{2}{1--0.5z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.5z^{-1})(1--0.5z^{-1})}$ and find $b_1$.","f":null,"o":["$2$","$0$","$4$","$1$"],"a":1,"s":"Numerator: $2(1--0.5z^{-1})+2(1-0.5z^{-1})=(2+2)-(0)z^{-1}$ ⇒ $b_0=4$, $b_1=0$.","m":2,"t":"Parallel form / partial fractions"},{"i":29,"q":"The $N=6$ poles of a Butterworth filter in the left half-plane are equally spaced on the circle. What is the angular spacing between adjacent poles (degrees)?","f":null,"o":["$15^\\circ$","$30^\\circ$","$60^\\circ$","$25.71^\\circ$"],"a":1,"s":"The $2N$ roots are spaced $\\pi/N$ apart: $180^\\circ/6=30^\\circ$.","m":2,"t":"Butterworth poles"},{"i":30,"q":"A drawback of the bilinear transform is …","f":null,"o":["aliasing","instability","loss of poles","nonlinear frequency warping"],"a":3,"s":"$\\Omega=2\\tan^{-1}(\\omega T/2)$ compresses high frequencies.","m":1,"t":"IIR design concepts"},{"i":31,"q":"For $H_a(s)=\\dfrac{1}{s+50}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/100$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$0.01$","$100$","$0.006065$","$1$"],"a":0,"s":"$h[0]=T_sh_a(0)=T_s=0.01$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":32,"q":"$H_a(s)=\\dfrac{100}{s+100}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$1$","$0.04878$","$0$","$0.025$"],"a":0,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":33,"q":"A parallel realisation uses $H(z)=\\dfrac{1}{1-0.6z^{-1}}+\\dfrac{1}{1-0.4z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.6z^{-1})(1-0.4z^{-1})}$ and find $b_1$.","f":null,"o":["$-2$","$1$","$2$","$-1$"],"a":3,"s":"Numerator: $1(1-0.4z^{-1})+1(1-0.6z^{-1})=(1+1)-(1)z^{-1}$ ⇒ $b_0=2$, $b_1=-1$.","m":2,"t":"Parallel form / partial fractions"},{"i":34,"q":"An order-2 Butterworth filter has $\\omega_c=1$ rad/s. What is the magnitude of each pole?","f":null,"o":["$0.5$","$1$","$2$","$0.7071$"],"a":1,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":35,"q":"A digital low-pass filter is to have its 3-dB frequency at $f_c=50$ Hz with $f_s=8000$ Hz. Using the bilinear transform with pre-warping, what analog cut-off $\\omega_c$ (rad/s) must be used in the analog prototype?","f":null,"o":["$314.1\\,\\mathrm{rad/s}$","$314.2\\,\\mathrm{rad/s}$","$628.6\\,\\mathrm{rad/s}$","$628.4\\,\\mathrm{rad/s}$"],"a":1,"s":"$\\Omega_c=2\\pi f_c/f_s=0.03927$ rad; $\\omega_c=\\dfrac{2}{T_s}\\tan\\dfrac{\\Omega_c}{2}=16000\\tan(0.01963)=314.2$ rad/s.","m":2,"t":"Frequency warping"},{"i":36,"q":"Find the minimum Butterworth order for a pass-band edge 200 rad/s with at most 3 dB loss and a stop-band edge 400 rad/s with at least 20 dB attenuation.","f":null,"o":["$3$","$4$","$5$","$7$"],"a":1,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[99.47]}{2\\log(2)}=3.318$ ⇒ $N=4$.","m":2,"t":"Butterworth order from specifications"},{"i":37,"q":"$H_a(s)=\\dfrac{200}{s+200}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$1$","$0$","$0.05$","$0.09524$"],"a":0,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":38,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1--0.5z^{-1})(1--0.25z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_2$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$0.625$","$-0.125$","$-0.75$","$0.125$"],"a":3,"s":"Expand: $(1--0.5z^{-1})(1--0.25z^{-1})=1-(-0.75)z^{-1}+(0.125)z^{-2}$ ⇒ $c_1=0.75$, $c_2=0.125$.","m":2,"t":"Cascade and parallel realisations"},{"i":39,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.5z^{-1})(1-0.25z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_1$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$-0.25$","$0.75$","$-0.75$","$0.125$"],"a":2,"s":"Expand: $(1-0.5z^{-1})(1-0.25z^{-1})=1-(0.75)z^{-1}+(0.125)z^{-2}$ ⇒ $c_1=-0.75$, $c_2=0.125$.","m":2,"t":"Cascade and parallel realisations"},{"i":40,"q":"A digital filter must have its cut-off at $f_c=2000$ Hz when sampled at $f_s=44100$ Hz. Find the digital cut-off frequency $\\Omega_c$ in rad/sample.","f":null,"o":["$0.285$","$1.257\\times10^{4}$","$0.04535$","$0.1425$"],"a":0,"s":"$\\Omega_c=2\\pi f_c/f_s=0.285$ rad/sample.","m":2,"t":"Digital cut-off from analog specs"},{"i":41,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{3}b_kz^{-k}}{1-\\sum_{k=1}^{4}a_kz^{-k}}$ is realised in direct form I. How many unit delays are needed?","f":null,"o":["$8$","$7$","$12$","$4$"],"a":1,"s":"Direct form I stores $M$ past inputs and $N$ past outputs: $3+4=7$.","m":2,"t":"Direct-form structures (hardware)"},{"i":42,"q":"$H_a(s)=\\dfrac{100}{s+100}$ is mapped by the bilinear transform $s=\\dfrac{2}{T_s}\\dfrac{1-z^{-1}}{1+z^{-1}}$ with $f_s=2000$ Hz. Find the pole of $H(z)$.","f":null,"o":["$0.9512$","$1.051$","$-0.9512$","$0.95$"],"a":0,"s":"$H(z)=\\dfrac{100}{\\frac{2}{T_s}\\frac{1-z^{-1}}{1+z^{-1}}+100}$. Pole: $z=\\dfrac{1-\\omega_cT_s/2}{1+\\omega_cT_s/2}=\\dfrac{1-0.025}{1+0.025}=0.9512$.","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":43,"q":"For the same digital cut-off ($f_c=2000$ Hz, $f_s=16000$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)","$\\omega_a&lt;2\\pi f_c$","$\\omega_a=2\\pi f_c$ always","$\\omega_a=\\pi f_c$"],"a":0,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=1.325\\times10^{4}$ rad/s versus $2\\pi f_c=1.257\\times10^{4}$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":44,"q":"$H_a(s)=\\dfrac{4000}{s+4000}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$0$","$1$","$0.2$","$0.3333$"],"a":1,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":45,"q":"A resonator has poles at $z=0.8e^{\\pm j\\pi/2}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_2$.","f":null,"o":["$0.8$","$0.64$","$1.28$","$0$"],"a":1,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.8)\\cos(\\pi/2)=0$, $c_2=0.64$.","m":2,"t":"Resonator pole placement"},{"i":46,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{4}b_kz^{-k}}{1-\\sum_{k=1}^{4}a_kz^{-k}}$ is realised in direct form II (canonical). How many unit delays are needed?","f":"<svg class=\"fg\" viewBox=\"0 0 330 310\" width=\"396\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 40.0L59.0 40.0\"/><path class=\"f\" d=\"M59.0 40.0L53.5 42.3L53.5 37.7Z\"/><text class=\"t\" x=\"8.0\" y=\"26.0\" text-anchor=\"start\">x[n]</text><circle class=\"w\" cx=\"70.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"70.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M80.0 40.0L260.0 40.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"40.0\" r=\"3\"/><text class=\"t\" x=\"176.0\" y=\"32.0\" text-anchor=\"middle\" style=\"font-size:11px\">b0 = 1</text><circle class=\"w\" cx=\"270.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"270.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M280.0 40.0L322.0 40.0\"/><path class=\"f\" d=\"M322.0 40.0L316.5 42.3L316.5 37.7Z\"/><text class=\"t\" x=\"324.0\" y=\"26.0\" text-anchor=\"end\">y[n]</text><path class=\"w\" d=\"M140.0 40.0L140.0 58.0\"/><rect class=\"w\" x=\"120.0\" y=\"58.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"74.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 82.0L140.0 100.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"100.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 100.0L140.0 118.0\"/><rect class=\"w\" x=\"120.0\" y=\"118.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"134.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 142.0L140.0 160.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"160.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 160.0L140.0 178.0\"/><rect class=\"w\" x=\"120.0\" y=\"178.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"194.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 202.0L140.0 220.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"220.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 220.0L140.0 238.0\"/><rect class=\"w\" x=\"120.0\" y=\"238.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"254.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 262.0L140.0 280.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"280.0\" r=\"3\"/><path class=\"w\" d=\"M70.0 50.0L70.0 280.0\"/><path class=\"w\" d=\"M140.0 100.0L70.0 100.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">a1 = 0.4</text><path class=\"w\" d=\"M140.0 160.0L70.0 160.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">a2 = 0.4</text><path class=\"w\" d=\"M140.0 220.0L70.0 220.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"220.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"214.0\" text-anchor=\"middle\" style=\"font-size:11px\">a3 = 0.4</text><path class=\"w\" d=\"M140.0 280.0L70.0 280.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"280.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"274.0\" text-anchor=\"middle\" style=\"font-size:11px\">a4 = 0.4</text><path class=\"w\" d=\"M270.0 50.0L270.0 280.0\"/><path class=\"w\" d=\"M140.0 100.0L270.0 100.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">b1 = 0.5</text><path class=\"w\" d=\"M140.0 160.0L270.0 160.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">b2 = 0.5</text><path class=\"w\" d=\"M140.0 220.0L270.0 220.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"220.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"214.0\" text-anchor=\"middle\" style=\"font-size:11px\">b3 = 0.5</text><path class=\"w\" d=\"M140.0 280.0L270.0 280.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"280.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"274.0\" text-anchor=\"middle\" style=\"font-size:11px\">b4 = 0.5</text></svg>","o":["$4$","$5$","$7$","$8$"],"a":0,"s":"The canonical form shares the delays: $\\max(M,N)=\\max(4,4)=4$.","m":2,"t":"Direct-form structures (hardware)"},{"i":47,"q":"A digital filter must have its cut-off at $f_c=2000$ Hz when sampled at $f_s=16000$ Hz. Find the digital cut-off frequency $\\Omega_c$ in rad/sample.","f":null,"o":["$1.257\\times10^{4}$","$0.3927$","$0.125$","$0.7854$"],"a":3,"s":"$\\Omega_c=2\\pi f_c/f_s=0.7854$ rad/sample.","m":2,"t":"Digital cut-off from analog specs"},{"i":48,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.5z^{-1})(1--0.5z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_1$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$1$","$-0.25$","$0.5$","$0$"],"a":3,"s":"Expand: $(1-0.5z^{-1})(1--0.5z^{-1})=1-(0)z^{-1}+(-0.25)z^{-2}$ ⇒ $c_1=0$, $c_2=-0.25$.","m":2,"t":"Cascade and parallel realisations"},{"i":49,"q":"For $H_a(s)=\\dfrac{1}{s+10}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/10$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$0.03679$","$0.1$","$1$","$10$"],"a":1,"s":"$h[0]=T_sh_a(0)=T_s=0.1$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":50,"q":"An analog filter has its 3-dB frequency at $\\omega_a=314.8$ rad/s. It is mapped by the bilinear transform with $T_s=1/2000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.1574$","$0.3122$","$0.1571$","$0.07854$"],"a":2,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.0787)=0.1571$ rad (compare the naive $\\omega_aT_s=0.1574$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":51,"q":"$H_a(s)=\\dfrac{1000}{s+1000}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$0$","$0.0625$","$0.1176$","$1$"],"a":3,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":52,"q":"For the same digital cut-off ($f_c=1000$ Hz, $f_s=8000$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a=2\\pi f_c$ always","$\\omega_a=\\pi f_c$","$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)","$\\omega_a&lt;2\\pi f_c$"],"a":2,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=6627$ rad/s versus $2\\pi f_c=6283$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":53,"q":"An IIR filter cannot in general have …","f":null,"o":["a sharp cut-off","exactly linear phase (causal and stable)","poles","a recursive structure"],"a":1,"s":"Causal stable IIR filters have non-linear phase.","m":1,"t":"IIR design concepts"},{"i":54,"q":"An analog filter $H_a(s)=\\dfrac{1}{s+100}$ is converted to digital by impulse invariance with $T_s=1/8000$ s. Find the pole of $H(z)$.","f":null,"o":["$0.9876$","$0.9875$","$0.0125$","$1.013$"],"a":0,"s":"A pole $s=-a$ maps to $z=e^{-aT_s}=e^{-100/8000}=0.9876$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":55,"q":"An analog filter has its 3-dB frequency at $\\omega_a=6498$ rad/s. It is mapped by the bilinear transform with $T_s=1/10000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.6498$","$0.6283$","$0.3142$","$1.153$"],"a":1,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.3249)=0.6283$ rad (compare the naive $\\omega_aT_s=0.6498$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":56,"q":"A Chebyshev type-I filter has 2 dB pass-band ripple, $|H|^2=\\dfrac1{1+\\epsilon^2C_N^2(\\omega/\\omega_p)}$. Find $\\epsilon$.","f":null,"o":["$0.5849$","$1.259$","$0.7648$","$0.2$"],"a":2,"s":"At the pass-band edge $C_N=1$: $10\\log(1+\\epsilon^2)=R_p$ ⇒ $\\epsilon=\\sqrt{10^{R_p/10}-1}=\\sqrt{10^{0.2}-1}=0.7648$.","m":2,"t":"Chebyshev ripple"},{"i":57,"q":"For the same digital cut-off ($f_c=500$ Hz, $f_s=44100$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a=2\\pi f_c$ always","$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)","$\\omega_a&lt;2\\pi f_c$","$\\omega_a=\\pi f_c$"],"a":1,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=3143$ rad/s versus $2\\pi f_c=3142$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":58,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{3}b_kz^{-k}}{1-\\sum_{k=1}^{2}a_kz^{-k}}$ is realised in direct form II. How many multipliers are needed?","f":null,"o":["$4$","$7$","$5$","$6$"],"a":3,"s":"$b_0\\dots b_M$ (4) and $a_1\\dots a_N$ (2): $6$.","m":2,"t":"Direct-form structures (hardware)"},{"i":59,"q":"A digital low-pass filter is to have its 3-dB frequency at $f_c=500$ Hz with $f_s=10000$ Hz. Using the bilinear transform with pre-warping, what analog cut-off $\\omega_c$ (rad/s) must be used in the analog prototype?","f":null,"o":["$3.129\\,\\mathrm{krad/s}$","$3.142\\,\\mathrm{krad/s}$","$6.498\\,\\mathrm{krad/s}$","$3.168\\,\\mathrm{krad/s}$"],"a":3,"s":"$\\Omega_c=2\\pi f_c/f_s=0.3142$ rad; $\\omega_c=\\dfrac{2}{T_s}\\tan\\dfrac{\\Omega_c}{2}=20000\\tan(0.1571)=3168$ rad/s.","m":2,"t":"Frequency warping"},{"i":60,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{1}b_kz^{-k}}{1-\\sum_{k=1}^{2}a_kz^{-k}}$ is realised in direct form I. How many unit delays are needed?","f":null,"o":["$6$","$4$","$3$","$2$"],"a":2,"s":"Direct form I stores $M$ past inputs and $N$ past outputs: $1+2=3$.","m":2,"t":"Direct-form structures (hardware)"},{"i":61,"q":"A parallel realisation uses $H(z)=\\dfrac{3}{1-0.8z^{-1}}+\\dfrac{3}{1-0.2z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.8z^{-1})(1-0.2z^{-1})}$ and find $b_1$.","f":null,"o":["$-3$","$6$","$-6$","$3$"],"a":0,"s":"Numerator: $3(1-0.2z^{-1})+3(1-0.8z^{-1})=(3+3)-(3)z^{-1}$ ⇒ $b_0=6$, $b_1=-3$.","m":2,"t":"Parallel form / partial fractions"},{"i":62,"q":"A Butterworth low-pass filter of order 3 has $\\omega_c=200$ rad/s. Find its attenuation (positive dB) at $\\omega=1000$ rad/s.","f":null,"o":["$9.03\\,\\mathrm{dB}$","$20.97\\,\\mathrm{dB}$","$41.94\\,\\mathrm{dB}$","$42.01\\,\\mathrm{dB}$"],"a":2,"s":"$A=10\\log_{10}\\bigl[1+(\\omega/\\omega_c)^{2N}\\bigr]=10\\log_{10}(1+5^{6})=41.94$ dB (≈ $20N\\log_{10}(\\omega/\\omega_c)$ far from the corner).","m":2,"t":"Butterworth magnitude"},{"i":63,"q":"A digital low-pass filter is to have its 3-dB frequency at $f_c=200$ Hz with $f_s=1000$ Hz. Using the bilinear transform with pre-warping, what analog cut-off $\\omega_c$ (rad/s) must be used in the analog prototype?","f":null,"o":["$6.155\\,\\mathrm{krad/s}$","$1.176\\,\\mathrm{krad/s}$","$1.257\\,\\mathrm{krad/s}$","$1.453\\,\\mathrm{krad/s}$"],"a":3,"s":"$\\Omega_c=2\\pi f_c/f_s=1.257$ rad; $\\omega_c=\\dfrac{2}{T_s}\\tan\\dfrac{\\Omega_c}{2}=2000\\tan(0.6283)=1453$ rad/s.","m":2,"t":"Frequency warping"},{"i":64,"q":"An analog filter $H_a(s)=\\dfrac{1}{s+50}$ is converted to digital by impulse invariance with $T_s=1/20$ s. Find the pole of $H(z)$.","f":null,"o":["$0.08208$","$-0.1111$","$-1.5$","$12.18$"],"a":0,"s":"A pole $s=-a$ maps to $z=e^{-aT_s}=e^{-50/20}=0.08208$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":65,"q":"An order-5 Butterworth filter has $\\omega_c=1000$ rad/s. What is the magnitude of each pole?","f":null,"o":["$707.1$","$1000$","$200$","$5000$"],"a":1,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":66,"q":"A Butterworth low-pass filter of order 6 has $\\omega_c=200$ rad/s. Find its attenuation (positive dB) at $\\omega=2000$ rad/s.","f":null,"o":["$120\\,\\mathrm{dB}$","$18.06\\,\\mathrm{dB}$","$60\\,\\mathrm{dB}$","$240\\,\\mathrm{dB}$"],"a":0,"s":"$A=10\\log_{10}\\bigl[1+(\\omega/\\omega_c)^{2N}\\bigr]=10\\log_{10}(1+10^{12})=120$ dB (≈ $20N\\log_{10}(\\omega/\\omega_c)$ far from the corner).","m":2,"t":"Butterworth magnitude"},{"i":67,"q":"$H_a(s)=\\dfrac{4000}{s+4000}$ is mapped by the bilinear transform $s=\\dfrac{2}{T_s}\\dfrac{1-z^{-1}}{1+z^{-1}}$ with $f_s=10000$ Hz. Find the pole of $H(z)$.","f":null,"o":["$0.6703$","$1.5$","$0.6$","$0.6667$"],"a":3,"s":"$H(z)=\\dfrac{4000}{\\frac{2}{T_s}\\frac{1-z^{-1}}{1+z^{-1}}+4000}$. Pole: $z=\\dfrac{1-\\omega_cT_s/2}{1+\\omega_cT_s/2}=\\dfrac{1-0.2}{1+0.2}=0.6667$.","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":68,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{2}b_kz^{-k}}{1-\\sum_{k=1}^{3}a_kz^{-k}}$ is realised in direct form II (canonical). How many unit delays are needed?","f":"<svg class=\"fg\" viewBox=\"0 0 330 250\" width=\"396\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 40.0L59.0 40.0\"/><path class=\"f\" d=\"M59.0 40.0L53.5 42.3L53.5 37.7Z\"/><text class=\"t\" x=\"8.0\" y=\"26.0\" text-anchor=\"start\">x[n]</text><circle class=\"w\" cx=\"70.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"70.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M80.0 40.0L260.0 40.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"40.0\" r=\"3\"/><text class=\"t\" x=\"176.0\" y=\"32.0\" text-anchor=\"middle\" style=\"font-size:11px\">b0 = 1</text><circle class=\"w\" cx=\"270.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"270.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M280.0 40.0L322.0 40.0\"/><path class=\"f\" d=\"M322.0 40.0L316.5 42.3L316.5 37.7Z\"/><text class=\"t\" x=\"324.0\" y=\"26.0\" text-anchor=\"end\">y[n]</text><path class=\"w\" d=\"M140.0 40.0L140.0 58.0\"/><rect class=\"w\" x=\"120.0\" y=\"58.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"74.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 82.0L140.0 100.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"100.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 100.0L140.0 118.0\"/><rect class=\"w\" x=\"120.0\" y=\"118.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"134.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 142.0L140.0 160.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"160.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 160.0L140.0 178.0\"/><rect class=\"w\" x=\"120.0\" y=\"178.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"194.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 202.0L140.0 220.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"220.0\" r=\"3\"/><path class=\"w\" d=\"M70.0 50.0L70.0 220.0\"/><path class=\"w\" d=\"M140.0 100.0L70.0 100.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">a1 = 0.4</text><path class=\"w\" d=\"M140.0 160.0L70.0 160.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">a2 = 0.4</text><path class=\"w\" d=\"M140.0 220.0L70.0 220.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"220.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"214.0\" text-anchor=\"middle\" style=\"font-size:11px\">a3 = 0.4</text><path class=\"w\" d=\"M270.0 50.0L270.0 160.0\"/><path class=\"w\" d=\"M140.0 100.0L270.0 100.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">b1 = 0.5</text><path class=\"w\" d=\"M140.0 160.0L270.0 160.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">b2 = 0.5</text></svg>","o":["$6$","$5$","$3$","$4$"],"a":2,"s":"The canonical form shares the delays: $\\max(M,N)=\\max(2,3)=3$.","m":2,"t":"Direct-form structures (hardware)"},{"i":69,"q":"A parallel realisation uses $H(z)=\\dfrac{2}{1-0.6z^{-1}}+\\dfrac{1}{1-0.4z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.6z^{-1})(1-0.4z^{-1})}$ and find $b_1$.","f":null,"o":["$-1.6$","$1.4$","$-1.4$","$1.6$"],"a":2,"s":"Numerator: $2(1-0.4z^{-1})+1(1-0.6z^{-1})=(2+1)-(1.4)z^{-1}$ ⇒ $b_0=3$, $b_1=-1.4$.","m":2,"t":"Parallel form / partial fractions"},{"i":70,"q":"An analog filter $H_a(s)=\\dfrac{1}{s+1}$ is converted to digital by impulse invariance with $T_s=1/50$ s. Find the pole of $H(z)$.","f":null,"o":["$1.02$","$0.98$","$0.9802$","$0.02$"],"a":2,"s":"A pole $s=-a$ maps to $z=e^{-aT_s}=e^{-1/50}=0.9802$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":71,"q":"An analog filter $H_a(s)=\\dfrac{1}{s+1}$ is converted to digital by impulse invariance with $T_s=1/20$ s. Find the pole of $H(z)$.","f":null,"o":["$0.9512$","$0.95$","$1.051$","$0.05$"],"a":0,"s":"A pole $s=-a$ maps to $z=e^{-aT_s}=e^{-1/20}=0.9512$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":72,"q":"A digital filter must have its cut-off at $f_c=2000$ Hz when sampled at $f_s=10000$ Hz. Find the digital cut-off frequency $\\Omega_c$ in rad/sample.","f":null,"o":["$1.257$","$1.257\\times10^{4}$","$0.6283$","$0.2$"],"a":0,"s":"$\\Omega_c=2\\pi f_c/f_s=1.257$ rad/sample.","m":2,"t":"Digital cut-off from analog specs"},{"i":73,"q":"A Chebyshev type-I filter has 3 dB pass-band ripple, $|H|^2=\\dfrac1{1+\\epsilon^2C_N^2(\\omega/\\omega_p)}$. Find $\\epsilon$.","f":null,"o":["$0.9953$","$1.413$","$0.3$","$0.9976$"],"a":3,"s":"At the pass-band edge $C_N=1$: $10\\log(1+\\epsilon^2)=R_p$ ⇒ $\\epsilon=\\sqrt{10^{R_p/10}-1}=\\sqrt{10^{0.3}-1}=0.9976$.","m":2,"t":"Chebyshev ripple"},{"i":74,"q":"A parallel realisation uses $H(z)=\\dfrac{2}{1-0.5z^{-1}}+\\dfrac{3}{1--0.5z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.5z^{-1})(1--0.5z^{-1})}$ and find $b_1$.","f":null,"o":["$0.5$","$-1$","$-0.5$","$5$"],"a":2,"s":"Numerator: $2(1--0.5z^{-1})+3(1-0.5z^{-1})=(2+3)-(0.5)z^{-1}$ ⇒ $b_0=5$, $b_1=-0.5$.","m":2,"t":"Parallel form / partial fractions"},{"i":75,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.5z^{-1})(1-0.1z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_2$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$-0.05$","$0.05$","$0.55$","$0.6$"],"a":1,"s":"Expand: $(1-0.5z^{-1})(1-0.1z^{-1})=1-(0.6)z^{-1}+(0.05)z^{-2}$ ⇒ $c_1=-0.6$, $c_2=0.05$.","m":2,"t":"Cascade and parallel realisations"},{"i":76,"q":"An order-3 Butterworth filter has $\\omega_c=1$ rad/s. What is the magnitude of each pole?","f":null,"o":["$0.3333$","$0.7071$","$3$","$1$"],"a":3,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":77,"q":"A parallel realisation uses $H(z)=\\dfrac{1}{1-0.8z^{-1}}+\\dfrac{3}{1-0.2z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.8z^{-1})(1-0.2z^{-1})}$ and find $b_1$.","f":null,"o":["$1.4$","$-2.6$","$-1.4$","$2.6$"],"a":1,"s":"Numerator: $1(1-0.2z^{-1})+3(1-0.8z^{-1})=(1+3)-(2.6)z^{-1}$ ⇒ $b_0=4$, $b_1=-2.6$.","m":2,"t":"Parallel form / partial fractions"},{"i":78,"q":"For the same digital cut-off ($f_c=3400$ Hz, $f_s=16000$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a=\\pi f_c$","$\\omega_a=2\\pi f_c$ always","$\\omega_a&lt;2\\pi f_c$","$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)"],"a":3,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=2.523\\times10^{4}$ rad/s versus $2\\pi f_c=2.136\\times10^{4}$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":79,"q":"$H_a(s)=\\dfrac{500}{s+500}$ is mapped by the bilinear transform $s=\\dfrac{2}{T_s}\\dfrac{1-z^{-1}}{1+z^{-1}}$ with $f_s=10000$ Hz. Find the pole of $H(z)$.","f":null,"o":["$1.051$","$0.9512$","$0.95$","$-0.9512$"],"a":1,"s":"$H(z)=\\dfrac{500}{\\frac{2}{T_s}\\frac{1-z^{-1}}{1+z^{-1}}+500}$. Pole: $z=\\dfrac{1-\\omega_cT_s/2}{1+\\omega_cT_s/2}=\\dfrac{1-0.025}{1+0.025}=0.9512$.","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":80,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.8z^{-1})(1-0.2z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_2$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$-0.16$","$0.66$","$1$","$0.16$"],"a":3,"s":"Expand: $(1-0.8z^{-1})(1-0.2z^{-1})=1-(1)z^{-1}+(0.16)z^{-2}$ ⇒ $c_1=-1$, $c_2=0.16$.","m":2,"t":"Cascade and parallel realisations"},{"i":81,"q":"A Butterworth low-pass filter of order 3 has $\\omega_c=1000$ rad/s. Find its attenuation (positive dB) at $\\omega=2000$ rad/s.","f":null,"o":["$18.06\\,\\mathrm{dB}$","$18.13\\,\\mathrm{dB}$","$9.06\\,\\mathrm{dB}$","$19.08\\,\\mathrm{dB}$"],"a":1,"s":"$A=10\\log_{10}\\bigl[1+(\\omega/\\omega_c)^{2N}\\bigr]=10\\log_{10}(1+2^{6})=18.13$ dB (≈ $20N\\log_{10}(\\omega/\\omega_c)$ far from the corner).","m":2,"t":"Butterworth magnitude"},{"i":82,"q":"A resonator has poles at $z=0.5e^{\\pm j\\pi/2}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_1$.","f":null,"o":["$-1$","$0.25$","$1$","$0$"],"a":3,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.5)\\cos(\\pi/2)=0$, $c_2=0.25$.","m":2,"t":"Resonator pole placement"},{"i":83,"q":"A Chebyshev type-I filter has $\\epsilon^2=1.0$. Find the pass-band ripple in dB.","f":null,"o":["$1.505\\,\\mathrm{dB}$","$0\\,\\mathrm{dB}$","$6.021\\,\\mathrm{dB}$","$3.01\\,\\mathrm{dB}$"],"a":3,"s":"$R_p=10\\log_{10}(1+\\epsilon^2)=10\\log_{10}(2)=3.01$ dB.","m":2,"t":"Chebyshev ripple"},{"i":84,"q":"An order-4 Butterworth filter has $\\omega_c=1000$ rad/s. What is the magnitude of each pole?","f":null,"o":["$250$","$4000$","$1000$","$707.1$"],"a":2,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":85,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.5z^{-1})(1--0.5z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_2$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$0$","$-0.5$","$-0.25$","$0.25$"],"a":2,"s":"Expand: $(1-0.5z^{-1})(1--0.5z^{-1})=1-(0)z^{-1}+(-0.25)z^{-2}$ ⇒ $c_1=0$, $c_2=-0.25$.","m":2,"t":"Cascade and parallel realisations"},{"i":86,"q":"An analog filter $H_a(s)=\\dfrac{1}{s+3}$ is converted to digital by impulse invariance with $T_s=1/100$ s. Find the pole of $H(z)$.","f":null,"o":["$1.03$","$0.97$","$0.9704$","$0.03$"],"a":2,"s":"A pole $s=-a$ maps to $z=e^{-aT_s}=e^{-3/100}=0.9704$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":87,"q":"A Chebyshev type-I filter has $\\epsilon^2=0.25$. Find the pass-band ripple in dB.","f":null,"o":["$-6.021\\,\\mathrm{dB}$","$0.969\\,\\mathrm{dB}$","$1.938\\,\\mathrm{dB}$","$3.522\\,\\mathrm{dB}$"],"a":1,"s":"$R_p=10\\log_{10}(1+\\epsilon^2)=10\\log_{10}(1.25)=0.9691$ dB.","m":2,"t":"Chebyshev ripple"},{"i":88,"q":"For $H_a(s)=\\dfrac{1}{s+2}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/1000$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$0.000998$","$1000$","$1$","$0.001$"],"a":3,"s":"$h[0]=T_sh_a(0)=T_s=0.001$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":89,"q":"Impulse invariance preserves …","f":null,"o":["the phase response exactly","the shape of the impulse response (samples of $h_a(t)$)","the frequency axis linearly for all frequencies","the magnitude response exactly"],"a":1,"s":"$h[n]=T_sh_a(nT_s)$ but aliasing distorts the magnitude.","m":1,"t":"IIR design concepts"},{"i":90,"q":"A parallel realisation uses $H(z)=\\dfrac{1}{1-0.5z^{-1}}+\\dfrac{2}{1-0.25z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.5z^{-1})(1-0.25z^{-1})}$ and find $b_1$.","f":null,"o":["$1.25$","$-1.25$","$-1$","$1$"],"a":1,"s":"Numerator: $1(1-0.25z^{-1})+2(1-0.5z^{-1})=(1+2)-(1.25)z^{-1}$ ⇒ $b_0=3$, $b_1=-1.25$.","m":2,"t":"Parallel form / partial fractions"},{"i":91,"q":"The bilinear transformation maps the left half of the $s$-plane to …","f":null,"o":["the right half $z$-plane","the interior of the unit circle","the real axis","the exterior of the unit circle"],"a":1,"s":"Stable analog filters become stable digital filters.","m":1,"t":"IIR design concepts"},{"i":92,"q":"An analog filter has its 3-dB frequency at $\\omega_a=1657$ rad/s. It is mapped by the bilinear transform with $T_s=1/2000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.8284$","$1.384$","$0.3927$","$0.7854$"],"a":3,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.4142)=0.7854$ rad (compare the naive $\\omega_aT_s=0.8284$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":93,"q":"For $H_a(s)=\\dfrac{1}{s+10}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/1000$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$1000$","$0.001$","$0.00099$","$1$"],"a":1,"s":"$h[0]=T_sh_a(0)=T_s=0.001$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":94,"q":"For $H_a(s)=\\dfrac{1}{s+10}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/20$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$1$","$0.03033$","$20$","$0.05$"],"a":3,"s":"$h[0]=T_sh_a(0)=T_s=0.05$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":95,"q":"A resonator has poles at $z=0.9e^{\\pm j\\pi/4}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_1$.","f":null,"o":["$1.273$","$-1.273$","$-1.8$","$0.81$"],"a":1,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.9)\\cos(\\pi/4)=-1.273$, $c_2=0.81$.","m":2,"t":"Resonator pole placement"},{"i":96,"q":"A resonator has poles at $z=0.5e^{\\pm j\\pi/2}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_2$.","f":null,"o":["$0.25$","$0.125$","$0$","$0.5$"],"a":0,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.5)\\cos(\\pi/2)=0$, $c_2=0.25$.","m":2,"t":"Resonator pole placement"},{"i":97,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.6z^{-1})(1-0.4z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_2$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$-0.24$","$0.24$","$1$","$0.74$"],"a":1,"s":"Expand: $(1-0.6z^{-1})(1-0.4z^{-1})=1-(1)z^{-1}+(0.24)z^{-2}$ ⇒ $c_1=-1$, $c_2=0.24$.","m":2,"t":"Cascade and parallel realisations"},{"i":98,"q":"A Chebyshev type-I filter has $\\epsilon^2=0.5$. Find the pass-band ripple in dB.","f":null,"o":["$-3.01\\,\\mathrm{dB}$","$3.522\\,\\mathrm{dB}$","$4.645\\,\\mathrm{dB}$","$1.761\\,\\mathrm{dB}$"],"a":3,"s":"$R_p=10\\log_{10}(1+\\epsilon^2)=10\\log_{10}(1.5)=1.761$ dB.","m":2,"t":"Chebyshev ripple"},{"i":99,"q":"A Chebyshev type-I filter has 0.5 dB pass-band ripple, $|H|^2=\\dfrac1{1+\\epsilon^2C_N^2(\\omega/\\omega_p)}$. Find $\\epsilon$.","f":null,"o":["$1.059$","$0.122$","$0.3493$","$0.05$"],"a":2,"s":"At the pass-band edge $C_N=1$: $10\\log(1+\\epsilon^2)=R_p$ ⇒ $\\epsilon=\\sqrt{10^{R_p/10}-1}=\\sqrt{10^{0.05}-1}=0.3493$.","m":2,"t":"Chebyshev ripple"},{"i":100,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{4}b_kz^{-k}}{1-\\sum_{k=1}^{1}a_kz^{-k}}$ is realised in direct form I. How many unit delays are needed?","f":null,"o":["$5$","$6$","$4$","$10$"],"a":0,"s":"Direct form I stores $M$ past inputs and $N$ past outputs: $4+1=5$.","m":2,"t":"Direct-form structures (hardware)"},{"i":101,"q":"For $H_a(s)=\\dfrac{1}{s+1}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/20$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$0.04756$","$20$","$0.05$","$1$"],"a":2,"s":"$h[0]=T_sh_a(0)=T_s=0.05$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":102,"q":"A Butterworth low-pass filter of order 4 has cut-off $\\omega_c=2000$ rad/s. Find $|H(j\\omega)|$ at $\\omega=1000.0$ rad/s.","f":null,"o":["$0.9961$","$0.9701$","$0.9981$","$0.7071$"],"a":2,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+0.5^{8}}$ ⇒ $|H|=0.9981$.","m":2,"t":"Butterworth magnitude"},{"i":103,"q":"An analog filter has its 3-dB frequency at $\\omega_a=1258$ rad/s. It is mapped by the bilinear transform with $T_s=1/10000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.1258$","$0.1257$","$0.2503$","$0.06283$"],"a":1,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.06291)=0.1257$ rad (compare the naive $\\omega_aT_s=0.1258$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":104,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.5z^{-1})(1-0.25z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_2$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$-0.125$","$0.625$","$0.125$","$0.75$"],"a":2,"s":"Expand: $(1-0.5z^{-1})(1-0.25z^{-1})=1-(0.75)z^{-1}+(0.125)z^{-2}$ ⇒ $c_1=-0.75$, $c_2=0.125$.","m":2,"t":"Cascade and parallel realisations"},{"i":105,"q":"The $N=2$ poles of a Butterworth filter in the left half-plane are equally spaced on the circle. What is the angular spacing between adjacent poles (degrees)?","f":null,"o":["$60^\\circ$","$45^\\circ$","$90^\\circ$","$180^\\circ$"],"a":2,"s":"The $2N$ roots are spaced $\\pi/N$ apart: $180^\\circ/2=90^\\circ$.","m":2,"t":"Butterworth poles"},{"i":106,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.9z^{-1})(1-0.5z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_1$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$1.4$","$0.45$","$-1.4$","$-0.9$"],"a":2,"s":"Expand: $(1-0.9z^{-1})(1-0.5z^{-1})=1-(1.4)z^{-1}+(0.45)z^{-2}$ ⇒ $c_1=-1.4$, $c_2=0.45$.","m":2,"t":"Cascade and parallel realisations"},{"i":107,"q":"A Butterworth low-pass filter of order 2 has cut-off $\\omega_c=2000$ rad/s. Find $|H(j\\omega)|$ at $\\omega=10000$ rad/s.","f":null,"o":["$0.001597$","$0.03997$","$0.7071$","$0.1961$"],"a":1,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+5^{4}}$ ⇒ $|H|=0.03997$.","m":2,"t":"Butterworth magnitude"},{"i":108,"q":"$H_a(s)=\\dfrac{2000}{s+2000}$ is mapped by the bilinear transform $s=\\dfrac{2}{T_s}\\dfrac{1-z^{-1}}{1+z^{-1}}$ with $f_s=10000$ Hz. Find the pole of $H(z)$.","f":null,"o":["$0.8187$","$0.8$","$0.8182$","$1.222$"],"a":2,"s":"$H(z)=\\dfrac{2000}{\\frac{2}{T_s}\\frac{1-z^{-1}}{1+z^{-1}}+2000}$. Pole: $z=\\dfrac{1-\\omega_cT_s/2}{1+\\omega_cT_s/2}=\\dfrac{1-0.1}{1+0.1}=0.8182$.","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":109,"q":"A Butterworth low-pass filter of order 6 has $\\omega_c=2000$ rad/s. Find its attenuation (positive dB) at $\\omega=1000.0$ rad/s.","f":null,"o":["$0.13\\,\\mathrm{dB}$","$18.06\\,\\mathrm{dB}$","$0\\,\\mathrm{dB}$","$-36.12\\,\\mathrm{dB}$"],"a":2,"s":"$A=10\\log_{10}\\bigl[1+(\\omega/\\omega_c)^{2N}\\bigr]=10\\log_{10}(1+0.5^{12})=0.00106$ dB (≈ $20N\\log_{10}(\\omega/\\omega_c)$ far from the corner).","m":2,"t":"Butterworth magnitude"},{"i":110,"q":"An analog filter has its 3-dB frequency at $\\omega_a=314.2$ rad/s. It is mapped by the bilinear transform with $T_s=1/10000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.06283$","$0.03142$","$0.06282$","$0.01571$"],"a":1,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.01571)=0.03142$ rad (compare the naive $\\omega_aT_s=0.03142$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":111,"q":"A Butterworth low-pass filter of order 5 has cut-off $\\omega_c=100$ rad/s. Find $|H(j\\omega)|$ at $\\omega=300$ rad/s.","f":null,"o":["$0.06402$","$0.7071$","$0.004115$","$1.693\\times10^{-5}$"],"a":2,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+3^{10}}$ ⇒ $|H|=0.004115$.","m":2,"t":"Butterworth magnitude"},{"i":112,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{4}b_kz^{-k}}{1-\\sum_{k=1}^{1}a_kz^{-k}}$ is realised in direct form II (canonical). How many unit delays are needed?","f":"<svg class=\"fg\" viewBox=\"0 0 330 310\" width=\"396\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 40.0L59.0 40.0\"/><path class=\"f\" d=\"M59.0 40.0L53.5 42.3L53.5 37.7Z\"/><text class=\"t\" x=\"8.0\" y=\"26.0\" text-anchor=\"start\">x[n]</text><circle class=\"w\" cx=\"70.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"70.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M80.0 40.0L260.0 40.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"40.0\" r=\"3\"/><text class=\"t\" x=\"176.0\" y=\"32.0\" text-anchor=\"middle\" style=\"font-size:11px\">b0 = 1</text><circle class=\"w\" cx=\"270.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"270.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M280.0 40.0L322.0 40.0\"/><path class=\"f\" d=\"M322.0 40.0L316.5 42.3L316.5 37.7Z\"/><text class=\"t\" x=\"324.0\" y=\"26.0\" text-anchor=\"end\">y[n]</text><path class=\"w\" d=\"M140.0 40.0L140.0 58.0\"/><rect class=\"w\" x=\"120.0\" y=\"58.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"74.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 82.0L140.0 100.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"100.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 100.0L140.0 118.0\"/><rect class=\"w\" x=\"120.0\" y=\"118.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"134.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 142.0L140.0 160.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"160.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 160.0L140.0 178.0\"/><rect class=\"w\" x=\"120.0\" y=\"178.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"194.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 202.0L140.0 220.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"220.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 220.0L140.0 238.0\"/><rect class=\"w\" x=\"120.0\" y=\"238.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"254.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 262.0L140.0 280.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"280.0\" r=\"3\"/><path class=\"w\" d=\"M70.0 50.0L70.0 100.0\"/><path class=\"w\" d=\"M140.0 100.0L70.0 100.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">a1 = 0.4</text><path class=\"w\" d=\"M270.0 50.0L270.0 280.0\"/><path class=\"w\" d=\"M140.0 100.0L270.0 100.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">b1 = 0.5</text><path class=\"w\" d=\"M140.0 160.0L270.0 160.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">b2 = 0.5</text><path class=\"w\" d=\"M140.0 220.0L270.0 220.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"220.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"214.0\" text-anchor=\"middle\" style=\"font-size:11px\">b3 = 0.5</text><path class=\"w\" d=\"M140.0 280.0L270.0 280.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"280.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"274.0\" text-anchor=\"middle\" style=\"font-size:11px\">b4 = 0.5</text></svg>","o":["$2$","$8$","$5$","$4$"],"a":3,"s":"The canonical form shares the delays: $\\max(M,N)=\\max(4,1)=4$.","m":2,"t":"Direct-form structures (hardware)"},{"i":113,"q":"A Chebyshev type-I filter has 1 dB pass-band ripple, $|H|^2=\\dfrac1{1+\\epsilon^2C_N^2(\\omega/\\omega_p)}$. Find $\\epsilon$.","f":null,"o":["$1.122$","$0.5088$","$0.1$","$0.2589$"],"a":1,"s":"At the pass-band edge $C_N=1$: $10\\log(1+\\epsilon^2)=R_p$ ⇒ $\\epsilon=\\sqrt{10^{R_p/10}-1}=\\sqrt{10^{0.1}-1}=0.5088$.","m":2,"t":"Chebyshev ripple"},{"i":114,"q":"An analog filter has its 3-dB frequency at $\\omega_a=1259$ rad/s. It is mapped by the bilinear transform with $T_s=1/8000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.3122$","$0.1571$","$0.07854$","$0.1574$"],"a":1,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.0787)=0.1571$ rad (compare the naive $\\omega_aT_s=0.1574$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":115,"q":"A parallel realisation uses $H(z)=\\dfrac{1}{1-0.5z^{-1}}+\\dfrac{1}{1-0.25z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.5z^{-1})(1-0.25z^{-1})}$ and find $b_1$.","f":null,"o":["$0.75$","$-1.5$","$-0.75$","$2$"],"a":2,"s":"Numerator: $1(1-0.25z^{-1})+1(1-0.5z^{-1})=(1+1)-(0.75)z^{-1}$ ⇒ $b_0=2$, $b_1=-0.75$.","m":2,"t":"Parallel form / partial fractions"},{"i":116,"q":"A resonator has poles at $z=0.5e^{\\pm j2\\pi/3}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_2$.","f":null,"o":["$0.25$","$0.5$","$0.125$","$0.375$"],"a":0,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.5)\\cos(2\\pi/3)=0.5$, $c_2=0.25$.","m":2,"t":"Resonator pole placement"},{"i":117,"q":"An order-3 Butterworth filter has $\\omega_c=1000$ rad/s. What is the magnitude of each pole?","f":null,"o":["$1000$","$333.3$","$3000$","$707.1$"],"a":0,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":118,"q":"$H_a(s)=\\dfrac{200}{s+200}$ is mapped by the bilinear transform $s=\\dfrac{2}{T_s}\\dfrac{1-z^{-1}}{1+z^{-1}}$ with $f_s=2000$ Hz. Find the pole of $H(z)$.","f":null,"o":["$1.105$","$0.9$","$-0.9048$","$0.9048$"],"a":3,"s":"$H(z)=\\dfrac{200}{\\frac{2}{T_s}\\frac{1-z^{-1}}{1+z^{-1}}+200}$. Pole: $z=\\dfrac{1-\\omega_cT_s/2}{1+\\omega_cT_s/2}=\\dfrac{1-0.05}{1+0.05}=0.9048$.","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":119,"q":"For $H_a(s)=\\dfrac{1}{s+100}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/100$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$100$","$0.003679$","$0.01$","$1$"],"a":2,"s":"$h[0]=T_sh_a(0)=T_s=0.01$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":120,"q":"Find the minimum Butterworth order for a pass-band edge 100 rad/s with at most 1 dB loss and a stop-band edge 400 rad/s with at least 50 dB attenuation.","f":null,"o":["$5$","$6$","$10$","$4$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[3.862\\times10^{5}]}{2\\log(4)}=4.64$ ⇒ $N=5$.","m":2,"t":"Butterworth order from specifications"},{"i":121,"q":"A parallel realisation uses $H(z)=\\dfrac{3}{1-0.6z^{-1}}+\\dfrac{3}{1-0.4z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.6z^{-1})(1-0.4z^{-1})}$ and find $b_1$.","f":null,"o":["$-3$","$-6$","$6$","$3$"],"a":0,"s":"Numerator: $3(1-0.4z^{-1})+3(1-0.6z^{-1})=(3+3)-(3)z^{-1}$ ⇒ $b_0=6$, $b_1=-3$.","m":2,"t":"Parallel form / partial fractions"},{"i":122,"q":"$H_a(s)=\\dfrac{200}{s+200}$ is mapped by the bilinear transform $s=\\dfrac{2}{T_s}\\dfrac{1-z^{-1}}{1+z^{-1}}$ with $f_s=8000$ Hz. Find the pole of $H(z)$.","f":null,"o":["$0.975$","$1.025$","$0.9753$","$-0.9753$"],"a":2,"s":"$H(z)=\\dfrac{200}{\\frac{2}{T_s}\\frac{1-z^{-1}}{1+z^{-1}}+200}$. Pole: $z=\\dfrac{1-\\omega_cT_s/2}{1+\\omega_cT_s/2}=\\dfrac{1-0.0125}{1+0.0125}=0.9753$.","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":123,"q":"A Butterworth low-pass filter of order 2 has cut-off $\\omega_c=100$ rad/s. Find $|H(j\\omega)|$ at $\\omega=200$ rad/s.","f":null,"o":["$0.05882$","$0.2425$","$0.7071$","$0.4472$"],"a":1,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+2^{4}}$ ⇒ $|H|=0.2425$.","m":2,"t":"Butterworth magnitude"},{"i":124,"q":"A resonator has poles at $z=0.8e^{\\pm j\\pi/3}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_1$.","f":null,"o":["$0.8$","$-1.6$","$0.64$","$-0.8$"],"a":3,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.8)\\cos(\\pi/3)=-0.8$, $c_2=0.64$.","m":2,"t":"Resonator pole placement"},{"i":125,"q":"A parallel realisation uses $H(z)=\\dfrac{1}{1-0.8z^{-1}}+\\dfrac{2}{1-0.2z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.8z^{-1})(1-0.2z^{-1})}$ and find $b_1$.","f":null,"o":["$1.8$","$-1.2$","$-1.8$","$1.2$"],"a":2,"s":"Numerator: $1(1-0.2z^{-1})+2(1-0.8z^{-1})=(1+2)-(1.8)z^{-1}$ ⇒ $b_0=3$, $b_1=-1.8$.","m":2,"t":"Parallel form / partial fractions"},{"i":126,"q":"The bilinear transformation maps the $j\\omega$ axis to …","f":null,"o":["the real axis","the origin","the unit circle","the imaginary axis"],"a":2,"s":"$s=j\\omega\\to z=e^{j\\Omega}$ with $\\Omega=2\\tan^{-1}(\\omega T/2)$.","m":1,"t":"IIR design concepts"},{"i":127,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{1}b_kz^{-k}}{1-\\sum_{k=1}^{1}a_kz^{-k}}$ is realised in direct form I. How many unit delays are needed?","f":null,"o":["$2$","$1$","$3$","$4$"],"a":0,"s":"Direct form I stores $M$ past inputs and $N$ past outputs: $1+1=2$.","m":2,"t":"Direct-form structures (hardware)"},{"i":128,"q":"An analog filter has its 3-dB frequency at $\\omega_a=3183$ rad/s. It is mapped by the bilinear transform with $T_s=1/8000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.7573$","$0.3978$","$0.1963$","$0.3927$"],"a":3,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.1989)=0.3927$ rad (compare the naive $\\omega_aT_s=0.3978$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":129,"q":"An order-6 Butterworth filter has $\\omega_c=2000$ rad/s. What is the magnitude of each pole?","f":null,"o":["$333.3$","$12000$","$1414$","$2000$"],"a":3,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":130,"q":"$H_a(s)=\\dfrac{2000}{s+2000}$ is mapped by the bilinear transform. Find $H(z)$ at $z=1$ (dc).","f":null,"o":["$0.1$","$0$","$0.1818$","$1$"],"a":3,"s":"$z=1\\leftrightarrow s=0$: $H(z=1)=H_a(0)=1$. The bilinear transform maps $\\Omega=0$ to $\\omega=0$ and $\\Omega=\\pi$ to $\\omega=\\infty$ (so a zero appears at $z=-1$).","m":2,"t":"Bilinear transformation: pole of a first-order filter"},{"i":131,"q":"The $N=5$ poles of a Butterworth filter in the left half-plane are equally spaced on the circle. What is the angular spacing between adjacent poles (degrees)?","f":null,"o":["$72^\\circ$","$36^\\circ$","$18^\\circ$","$30^\\circ$"],"a":1,"s":"The $2N$ roots are spaced $\\pi/N$ apart: $180^\\circ/5=36^\\circ$.","m":2,"t":"Butterworth poles"},{"i":132,"q":"An order-4 Butterworth filter has $\\omega_c=500$ rad/s. What is the magnitude of each pole?","f":null,"o":["$353.6$","$500$","$125$","$2000$"],"a":1,"s":"All poles lie on a circle of radius $\\omega_c$.","m":2,"t":"Butterworth poles"},{"i":133,"q":"Find the minimum Butterworth order for a pass-band edge 100 rad/s with at most 1 dB loss and a stop-band edge 150 rad/s with at least 40 dB attenuation.","f":null,"o":["$15$","$14$","$13$","$27$"],"a":1,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[3.862\\times10^{4}]}{2\\log(1.5)}=13.02$ ⇒ $N=14$.","m":2,"t":"Butterworth order from specifications"},{"i":134,"q":"A Butterworth low-pass filter of order 4 has $\\omega_c=100$ rad/s. Find its attenuation (positive dB) at $\\omega=1000$ rad/s.","f":null,"o":["$12.04\\,\\mathrm{dB}$","$40\\,\\mathrm{dB}$","$80\\,\\mathrm{dB}$","$160\\,\\mathrm{dB}$"],"a":2,"s":"$A=10\\log_{10}\\bigl[1+(\\omega/\\omega_c)^{2N}\\bigr]=10\\log_{10}(1+10^{8})=80$ dB (≈ $20N\\log_{10}(\\omega/\\omega_c)$ far from the corner).","m":2,"t":"Butterworth magnitude"},{"i":135,"q":"Find the minimum Butterworth order for a pass-band edge 500 rad/s with at most 2 dB loss and a stop-band edge 750 rad/s with at least 30 dB attenuation.","f":null,"o":["$10$","$19$","$11$","$9$"],"a":0,"s":"$N\\ge\\dfrac{\\log\\left[(10^{0.1A_s}-1)/(10^{0.1A_p}-1)\\right]}{2\\log(\\omega_s/\\omega_p)}=\\dfrac{\\log[1708]}{2\\log(1.5)}=9.178$ ⇒ $N=10$.","m":2,"t":"Butterworth order from specifications"},{"i":136,"q":"For the same digital cut-off ($f_c=3400$ Hz, $f_s=8000$ Hz) the bilinear transform with pre-warping needs an analog cut-off $\\omega_a=\\dfrac{2}{T_s}\\tan(\\Omega_c/2)$. Compare it with the un-warped $2\\pi f_c$: which is larger?","f":null,"o":["$\\omega_a=2\\pi f_c$ always","$\\omega_a>2\\pi f_c$ (tan grows faster than its argument)","$\\omega_a&lt;2\\pi f_c$","$\\omega_a=\\pi f_c$"],"a":1,"s":"$\\tan x>x$ for $0&lt;x&lt;\\pi/2$ ⇒ $\\omega_a=6.664\\times10^{4}$ rad/s versus $2\\pi f_c=2.136\\times10^{4}$ rad/s.","m":2,"t":"Digital cut-off from analog specs"},{"i":137,"q":"A parallel realisation uses $H(z)=\\dfrac{1}{1-0.5z^{-1}}+\\dfrac{3}{1--0.5z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.5z^{-1})(1--0.5z^{-1})}$ and find $b_1$.","f":null,"o":["$-2$","$4$","$1$","$-1$"],"a":3,"s":"Numerator: $1(1--0.5z^{-1})+3(1-0.5z^{-1})=(1+3)-(1)z^{-1}$ ⇒ $b_0=4$, $b_1=-1$.","m":2,"t":"Parallel form / partial fractions"},{"i":138,"q":"A parallel realisation uses $H(z)=\\dfrac{3}{1-0.6z^{-1}}+\\dfrac{1}{1-0.4z^{-1}}$. Combine into $\\dfrac{b_0+b_1z^{-1}}{(1-0.6z^{-1})(1-0.4z^{-1})}$ and find $b_1$.","f":null,"o":["$-2.2$","$-1.8$","$2.2$","$1.8$"],"a":1,"s":"Numerator: $3(1-0.4z^{-1})+1(1-0.6z^{-1})=(3+1)-(1.8)z^{-1}$ ⇒ $b_0=4$, $b_1=-1.8$.","m":2,"t":"Parallel form / partial fractions"},{"i":139,"q":"A resonator has poles at $z=0.8e^{\\pm j2\\pi/3}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_1$.","f":null,"o":["$0.64$","$-1.6$","$-0.8$","$0.8$"],"a":3,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.8)\\cos(2\\pi/3)=0.8$, $c_2=0.64$.","m":2,"t":"Resonator pole placement"},{"i":140,"q":"A resonator has poles at $z=0.95e^{\\pm j\\pi/2}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_1$.","f":null,"o":["$0$","$0.9025$","$1$","$-1.9$"],"a":0,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.95)\\cos(\\pi/2)=0$, $c_2=0.9025$.","m":2,"t":"Resonator pole placement"},{"i":141,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{1}b_kz^{-k}}{1-\\sum_{k=1}^{2}a_kz^{-k}}$ is realised in direct form II. How many multipliers are needed?","f":null,"o":["$8$","$4$","$3$","$2$"],"a":1,"s":"$b_0\\dots b_M$ (2) and $a_1\\dots a_N$ (2): $4$.","m":2,"t":"Direct-form structures (hardware)"},{"i":142,"q":"An IIR filter $H(z)=\\dfrac{\\sum_{k=0}^{2}b_kz^{-k}}{1-\\sum_{k=1}^{4}a_kz^{-k}}$ is realised in direct form II (canonical). How many unit delays are needed?","f":"<svg class=\"fg\" viewBox=\"0 0 330 310\" width=\"396\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 40.0L59.0 40.0\"/><path class=\"f\" d=\"M59.0 40.0L53.5 42.3L53.5 37.7Z\"/><text class=\"t\" x=\"8.0\" y=\"26.0\" text-anchor=\"start\">x[n]</text><circle class=\"w\" cx=\"70.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"70.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M80.0 40.0L260.0 40.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"40.0\" r=\"3\"/><text class=\"t\" x=\"176.0\" y=\"32.0\" text-anchor=\"middle\" style=\"font-size:11px\">b0 = 1</text><circle class=\"w\" cx=\"270.0\" cy=\"40.0\" r=\"10\"/><text class=\"t\" x=\"270.0\" y=\"44.0\" text-anchor=\"middle\">+</text><path class=\"w\" d=\"M280.0 40.0L322.0 40.0\"/><path class=\"f\" d=\"M322.0 40.0L316.5 42.3L316.5 37.7Z\"/><text class=\"t\" x=\"324.0\" y=\"26.0\" text-anchor=\"end\">y[n]</text><path class=\"w\" d=\"M140.0 40.0L140.0 58.0\"/><rect class=\"w\" x=\"120.0\" y=\"58.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"74.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 82.0L140.0 100.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"100.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 100.0L140.0 118.0\"/><rect class=\"w\" x=\"120.0\" y=\"118.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"134.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 142.0L140.0 160.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"160.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 160.0L140.0 178.0\"/><rect class=\"w\" x=\"120.0\" y=\"178.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"194.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 202.0L140.0 220.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"220.0\" r=\"3\"/><path class=\"w\" d=\"M140.0 220.0L140.0 238.0\"/><rect class=\"w\" x=\"120.0\" y=\"238.0\" width=\"40.0\" height=\"24.0\"/><text class=\"t\" x=\"140.0\" y=\"254.0\" text-anchor=\"middle\">z⁻¹</text><path class=\"w\" d=\"M140.0 262.0L140.0 280.0\"/><circle class=\"f\" cx=\"140.0\" cy=\"280.0\" r=\"3\"/><path class=\"w\" d=\"M70.0 50.0L70.0 280.0\"/><path class=\"w\" d=\"M140.0 100.0L70.0 100.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">a1 = 0.4</text><path class=\"w\" d=\"M140.0 160.0L70.0 160.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">a2 = 0.4</text><path class=\"w\" d=\"M140.0 220.0L70.0 220.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"220.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"214.0\" text-anchor=\"middle\" style=\"font-size:11px\">a3 = 0.4</text><path class=\"w\" d=\"M140.0 280.0L70.0 280.0\"/><circle class=\"f\" cx=\"70.0\" cy=\"280.0\" r=\"3\"/><text class=\"t\" x=\"105.0\" y=\"274.0\" text-anchor=\"middle\" style=\"font-size:11px\">a4 = 0.4</text><path class=\"w\" d=\"M270.0 50.0L270.0 160.0\"/><path class=\"w\" d=\"M140.0 100.0L270.0 100.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"100.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"94.0\" text-anchor=\"middle\" style=\"font-size:11px\">b1 = 0.5</text><path class=\"w\" d=\"M140.0 160.0L270.0 160.0\"/><circle class=\"f\" cx=\"270.0\" cy=\"160.0\" r=\"3\"/><text class=\"t\" x=\"205.0\" y=\"154.0\" text-anchor=\"middle\" style=\"font-size:11px\">b2 = 0.5</text></svg>","o":["$4$","$5$","$3$","$6$"],"a":0,"s":"The canonical form shares the delays: $\\max(M,N)=\\max(2,4)=4$.","m":2,"t":"Direct-form structures (hardware)"},{"i":143,"q":"For $H_a(s)=\\dfrac{1}{s+50}$, impulse invariance (with $h[n]=T_sh_a(nT_s)$, $T_s=1/8000$ s) gives $H(z)=\\dfrac{T_s}{1-e^{-aT_s}z^{-1}}$. Find $h[0]$.","f":null,"o":["$1$","$8000$","$0.0001242$","$0.000125$"],"a":3,"s":"$h[0]=T_sh_a(0)=T_s=0.000125$.","m":2,"t":"Impulse invariance: pole mapping"},{"i":144,"q":"A Butterworth low-pass filter of order 4 has cut-off $\\omega_c=200$ rad/s. Find $|H(j\\omega)|$ at $\\omega=600$ rad/s.","f":null,"o":["$0.01234$","$0.0001524$","$0.1104$","$0.7071$"],"a":0,"s":"$|H|^2=\\dfrac1{1+(\\omega/\\omega_c)^{2N}}=\\dfrac1{1+3^{8}}$ ⇒ $|H|=0.01234$.","m":2,"t":"Butterworth magnitude"},{"i":145,"q":"Impulse invariance is unsuitable for designing high-pass filters because …","f":null,"o":["it needs complex coefficients","it changes the number of poles","it always gives unstable filters","the digital response is aliased (the analog response is not bandlimited)"],"a":3,"s":"The periodic repetition of the analog response overlaps for non-bandlimited (high-pass) prototypes.","m":1,"t":"IIR design concepts"},{"i":146,"q":"A resonator has poles at $z=0.5e^{\\pm j\\pi/3}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_2$.","f":null,"o":["$-0.5$","$0.5$","$0.25$","$0.125$"],"a":2,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.5)\\cos(\\pi/3)=-0.5$, $c_2=0.25$.","m":2,"t":"Resonator pole placement"},{"i":147,"q":"An analog filter has its 3-dB frequency at $\\omega_a=628.6$ rad/s. It is mapped by the bilinear transform with $T_s=1/8000$ s. Find the digital 3-dB frequency $\\Omega$ (rad).","f":null,"o":["$0.07858$","$0.03927$","$0.07854$","$0.1568$"],"a":2,"s":"$\\Omega=2\\tan^{-1}(\\omega_aT_s/2)=2\\tan^{-1}(0.03929)=0.07854$ rad (compare the naive $\\omega_aT_s=0.07858$ rad: the warping).","m":2,"t":"Frequency warping"},{"i":148,"q":"A resonator has poles at $z=0.95e^{\\pm j2\\pi/3}$. Its denominator is $1+c_1z^{-1}+c_2z^{-2}$. Find $c_2$.","f":null,"o":["$0.9025$","$1.805$","$0.95$","$0.4512$"],"a":0,"s":"$(1-re^{j\\theta}z^{-1})(1-re^{-j\\theta}z^{-1})=1-2r\\cos\\theta\\,z^{-1}+r^2z^{-2}$ ⇒ $c_1=-2(0.95)\\cos(2\\pi/3)=0.95$, $c_2=0.9025$.","m":2,"t":"Resonator pole placement"},{"i":149,"q":"A cascade of two first-order sections $H(z)=\\dfrac{1}{(1-0.8z^{-1})(1-0.2z^{-1})}$ is implemented as a single direct-form section $\\dfrac{1}{1+c_1z^{-1}+c_2z^{-2}}$. Find $c_1$.","f":"<svg class=\"fg\" viewBox=\"0 0 260 70\" width=\"312\" role=\"img\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"w\" d=\"M8.0 35.0L80.0 35.0\"/><path class=\"f\" d=\"M80.0 35.0L74.5 37.3L74.5 32.7Z\"/><text class=\"t\" x=\"6.0\" y=\"22.0\" text-anchor=\"start\">x[n]</text><rect class=\"w\" x=\"80.0\" y=\"14.0\" width=\"100.0\" height=\"42.0\"/><text class=\"t\" x=\"130.0\" y=\"39.0\" text-anchor=\"middle\">H₁(z) · H₂(z)</text><path class=\"w\" d=\"M180.0 35.0L252.0 35.0\"/><path class=\"f\" d=\"M252.0 35.0L246.5 37.3L246.5 32.7Z\"/><text class=\"t\" x=\"254.0\" y=\"22.0\" text-anchor=\"end\">y[n]</text></svg>","o":["$-1$","$0.16$","$-0.5$","$1$"],"a":0,"s":"Expand: $(1-0.8z^{-1})(1-0.2z^{-1})=1-(1)z^{-1}+(0.16)z^{-2}$ ⇒ $c_1=-1$, $c_2=0.16$.","m":2,"t":"Cascade and parallel realisations"},{"i":150,"q":"A Chebyshev type-I filter has $\\epsilon^2=0.1$. Find the pass-band ripple in dB.","f":null,"o":["$2.387\\,\\mathrm{dB}$","$0.828\\,\\mathrm{dB}$","$0.414\\,\\mathrm{dB}$","$-10\\,\\mathrm{dB}$"],"a":2,"s":"$R_p=10\\log_{10}(1+\\epsilon^2)=10\\log_{10}(1.1)=0.4139$ dB.","m":2,"t":"Chebyshev ripple"}]};